/* Product CMS: public imagery and private print originals use distinct stores.
 * Changes stay local. Publishing never writes the approved public repository. */
(() => {
 'use strict';
 const A=window.AdminUI,S=A.S,V=window.StudioMedia,U=window.StudioUI;
 const {esc,money,button,actions,pill,panel,notice,field,select,textarea,check,form,details,link,facts,modal}=A;
 const slots=[['frame-white','White frame'],['close-white','White frame - close-up'],['frame-black','Black frame'],['close-black','Black frame - close-up'],['frame-antique-gold','Antique gold frame'],['close-antique-gold','Antique gold - close-up'],['paper','Paper / unframed'],['artwork','Public artwork image']];
 const find=id=>{const p=S.state.products.find(x=>x.id===id);if(!p)throw Error('This product is no longer available.');return p;};
 const base=p=>window.AdminPublicCatalogue.find(x=>x.slug===(window.AdminCatalogue.find(y=>y.id===p.id)?.slug||p.publicSourceSlug||p.slug));
 const ph=(p,tab='details')=>U.query('products',{id:p.id,tab},false);
 function snapshot(p,reason){const old=S.clone(p);delete old.history;p.history.unshift({at:S.now(),reason,snapshot:old});p.version++;}
 function change(p,label,fn,reason=label){S.mutate(p.id,label,()=>{snapshot(p,reason);fn();},reason);if(S.storageError)throw Error(S.storageError);}
 function source(p,slot){const b=base(p);if(!b)return '';if(slot.startsWith('frame-'))return b.frames[slot.slice(6)]?.image?.src||'';if(slot.startsWith('close-'))return b.frames[slot.slice(6)]?.closeup?.src||b.frames[slot.slice(6)]?.close?.src||'';return b[slot]?.src||'';}
 function publicId(p,slot){return p.cms.media[slot]||'';}
 function image(p,slot){const id=publicId(p,slot),url=id?V.url(id):'',fallback='../assets/artwork-originals/'+p.slug+'.webp',src=source(p,slot);return `<img src="${esc(url||(src?'../'+src:fallback))}" alt="${esc(V.publicItems.find(x=>x.id===id)?.alt||p.cms.alt||p.title)}" data-fallback="${esc(fallback)}" loading="lazy">`;}
 const inputFile=(label,accept='image/png,image/jpeg,image/webp')=>`<label class="field"><span>${esc(label)}</span><input name="file" aria-label="${esc(label)}" type="file" accept="${esc(accept)}" required></label>`;
 const dirtyForm=(...args)=>form(...args).replace('<form ','<form data-dirty="1" ');
 const versionCheck=(p,v)=>{if(Number(p.version)!==Number(v))throw Error('This product changed in another action. Reload before saving.');};
 function checks(p){const missing=[];if(!p.title?.trim())missing.push('Add a product name.');if(!p.copy?.trim())missing.push('Add a product description.');if(!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(p.slug||''))missing.push('Use a valid lowercase URL slug.');if(S.state.products.some(x=>x.id!==p.id&&x.slug===p.slug))missing.push('This URL slug belongs to another product.');for(const [slot,label] of slots){const id=publicId(p,slot);if(id&&!V.publicItems.some(x=>x.id===id&&!x.general))missing.push('Restore the uploaded '+label.toLowerCase()+'.');else if(!id&&!source(p,slot))missing.push('Add the '+label.toLowerCase()+' image.');}if(!p.cms.seoTitle?.trim())missing.push('Add an SEO title.');if(!p.cms.seoDescription?.trim())missing.push('Add an SEO description.');if(!p.cms.alt?.trim())missing.push('Add an image description.');for(const [k,v] of Object.entries(p.prices))if(!Number.isSafeInteger(v)||v<=0)missing.push('Check the '+k+' price.');if(!p.rights)missing.push('Review the artwork rights.');if(!p.fileApproved)missing.push('Approve the print-file version.');if(!p.sample)missing.push('Approve the physical sample.');if(p.printFileId&&!V.privateItems.some(x=>x.id===p.printFileId))missing.push('Restore the private print original for '+p.fileVersion+'.');return missing;}
 function detailsEditor(p){return dirtyForm('cms-details',`<div class="field-grid">${field('title','Product name',p.title)}${field('slug','URL slug',p.slug,'text','Changing a URL here changes only the local draft.')}</div>`+textarea('copy','Product description / story',p.copy,false)+`<div class="field-grid">${field('collection','Collection',p.collection,'text','',false)}${field('style','Art style',p.style,'text','',false)}${select('orientation','Orientation',['Portrait','Landscape','Square'],p.cms.orientation)}${select('frame','Default frame',[['black','Black'],['white','White'],['antique-gold','Antique Gold']],p.cms.suggestedFrame)}${field('rooms','Rooms',(p.rooms||[]).join(', '),'text','Separate with commas.',false)}${field('moods','Moods',(p.moods||[]).join(', '),'text','Separate with commas.',false)}${field('palettes','Colour palettes',(p.cms.palettes||[]).join(', '),'text','Separate with commas.',false)}${field('lead','Production lead time',p.lead||'5-7 working days')}</div>`+textarea('hook','Short introduction',p.cms.hook,false)+details('Prices & display',`<p class="small">A2 / 42 x 59.4 cm. The three approved frame finishes remain unchanged.</p><div class="field-grid">${['black','white','antique-gold'].map(k=>field(k,k==='antique-gold'?'Antique Gold price (INR)':k[0].toUpperCase()+k.slice(1)+' price (INR)',p.prices[k]/100,'number')).join('')}</div>`+check('featured','Feature this product in the existing collection layout',p.featured))+field('reason','Change note','Catalogue update','text','Recorded in the product history.'),'Save draft',{id:p.id,version:p.version});}
 function imagesEditor(p){return `<p class="small">Product-page images only. PNG, JPEG or WebP, up to 25 MB. Previews are compressed; originals are retained. Never upload a confidential print master here.</p><div class="media-grid">${slots.map(([slot,label])=>{const id=publicId(p,slot),f=V.publicItems.find(x=>x.id===id);return `<section class="media-card"><div class="media-preview">${image(p,slot)}</div><div class="media-info"><h3>${esc(label)}</h3><p class="small">${f?esc(f.name)+' / '+f.width+' x '+f.height:source(p,slot)?'Approved public asset reference':'Image required'}</p>${actions(button('public-upload',f?'Replace image':'Upload image',{id:p.id,slot},'button secondary small-button'),f?button('public-download','Original',{id},'button secondary small-button'):'',f?button('public-remove','Remove override',{id:p.id,slot},'text-button'):'')}</div></section>`;}).join('')}</div>`+details('Shared size, material & craft images',`<p>These images are maintained once and reused by the approved product templates.</p>`+link('products/general','Manage general images','button secondary'));}
 function fileRows(p,kind){const records=V.privateItems.filter(f=>f.product===p.id&&f.kind===kind).sort((a,b)=>b.created.localeCompare(a.created));return records.length?records.map(f=>{const pinned=S.state.orders.flatMap(o=>o.items.filter(i=>i.privateFileId===f.id||!i.privateFileId&&i.artId===p.id&&i.stage>=2&&i.file===f.version).map(i=>o.id+' / '+i.id));return `<article class="file-row"><div class="file-icon" aria-hidden="true">${kind==='print'?'P':'A'}</div><div class="file-meta"><strong>${esc(f.name)}</strong><p class="small">${esc(f.version)} / ${(f.size/1024/1024).toFixed(2)} MB / ${esc(f.created.slice(0,10))}${p.printFileId===f.id?' / Current print master':''}</p>${f.note?`<p class="small">${esc(f.note)}</p>`:''}${pinned.length?`<p class="small">Pinned to ${esc(pinned.join(', '))}. This file is retained.</p>`:''}${details('Verification fingerprint',`<code class="hash-code">SHA-256 ${esc(f.sha)}</code>`)}</div>${button('private-download','Download original',{id:f.id},'button secondary')}</article>`;}).join(''):`<p class="inline-message">No ${kind==='print'?'print originals':'approval evidence'} uploaded for this product.</p>`;}
 function vaultBar(){return `<div class="vault-status"><div><strong>${V.isUnlocked?'Private vault unlocked':V.hasVault?'Private vault locked':'Set up your private vault'}</strong><p class="small">Encrypted in this browser. Never added to public images or shared-image exports.</p></div>${V.isUnlocked?button('vault-lock','Lock vault',{},'button secondary'):button('vault-unlock',V.hasVault?'Unlock vault':'Create passphrase',{},'button secondary')}</div>`;}
 function filesEditor(p){return vaultBar()+`<div class="section-line"><div><h3>Print originals</h3><p class="small">Download the unchanged master to print an order. New versions never replace a released job's pinned file.</p></div>${button('private-upload','Upload print file',{id:p.id,kind:'print'},'button')}</div>`+fileRows(p,'print')+`<div class="section-line"><div><h3>Approval evidence</h3><p class="small">Rights, sample approval and production evidence. Kept out of the public image library.</p></div>${button('private-upload','Add approval evidence',{id:p.id,kind:'approval'},'button secondary')}</div>`+fileRows(p,'approval')+details('Version approvals',facts([['Current print version',esc(p.fileVersion)],['Artwork rights',p.rights?'Approved in prototype':'Review required'],['Print file',p.fileApproved?'Approved in prototype':'Review required'],['Physical sample',p.sample?'Approved in prototype':'Review required']])+actions(button('cms-approvals','Review approvals',{id:p.id},'button secondary')))+`<p class="small">Keep your source files and download a backup from Staff & Access. Local storage is not a shared cloud drive. Losing the passphrase means encrypted contents cannot be recovered.</p>`;}
 function reviewEditor(p){const missing=checks(p);return dirtyForm('cms-seo',field('seoTitle','SEO page title',p.cms.seoTitle,'text','',false)+textarea('seoDescription','SEO description',p.cms.seoDescription,false)+textarea('alt','Default image description',p.cms.alt,false)+details('Internal research',textarea('keywords','Research keywords / planning notes',p.cms.searchKeywords||'',false)),'Save SEO draft',{id:p.id,version:p.version})+`<div class="seo-preview"><small>your-website / products / ${esc(p.slug)}</small><h3>${esc(p.cms.seoTitle||p.title)}</h3><p>${esc(p.cms.seoDescription)}</p></div>`+(missing.length?notice('Before publishing',missing.map(esc).join('<br>'),'warn'):notice('Ready for demo publication','Required fields and prototype approvals are present. This does not verify a live integration.'))+actions(link('products/preview?id='+encodeURIComponent(p.id),'Preview product','button secondary'),button('art-publish','Publish in demo',{id:p.id}))+`<p class="small">Publication validates the local draft. No public page, deployment, search index or provider account is changed.</p>`;}
 function editor(p){const tab=A.params.get('tab')||'details';return `<section class="record-workspace" id="product-workspace"><header class="record-top"><div><p class="eyebrow">PRODUCT / ${esc(p.id)}</p><h2>${esc(p.title)}</h2><div class="status-strip">${U.statePill(p)}${pill('Revision '+p.version,'neutral')}</div></div><div class="actions">${link('products/preview?id='+encodeURIComponent(p.id),'Preview','button secondary')}<details class="record-menu"><summary>More</summary><div>${button('art-status','Pause / archive / review',{id:p.id},'text-button')}${button('cms-delete','Delete unused draft',{id:p.id},'text-button')}</div></details></div></header><nav class="workspace-tabs" aria-label="Product editor">${[['details','Details & prices'],['images','Public images'],['files','Private files'],['review','SEO & publish']].map(([id,t])=>`<a href="#${esc(ph(p,id))}"${id===tab?' aria-current="page"':''}>${t}</a>`).join('')}</nav><div class="editor-body">${tab==='images'?imagesEditor(p):tab==='files'?filesEditor(p):tab==='review'?reviewEditor(p):detailsEditor(p)}${details('Revision history',p.history.length?A.table('Saved product revisions',['Revision','Change','Date','Restore'],p.history.map((h,n)=>['v'+h.snapshot.version,esc(h.reason),esc(h.at.slice(0,10)),button('art-rollback','Restore as draft',{id:p.id,index:n},'button secondary small-button')])):'<p>No local revisions yet.</p>')}</div></section>`;}
 A.screens.products=()=>{const q=(A.params.get('q')||'').toLowerCase(),status=A.params.get('status')||'All';let ps=S.state.products.filter(p=>[p.id,p.title,p.collection,p.style].join(' ').toLowerCase().includes(q)&&(status==='All'||p.status===status));ps.sort((a,b)=>a.title.localeCompare(b.title));const pg=U.paginate(ps,'products'),selected=S.state.products.find(p=>p.id===A.params.get('id')),rows=pg.rows.map(p=>({id:p.id,href:ph(p),cells:[`<div class="product-cell">${U.pic(p)}<div>${link(ph(p),p.title)}<small>${esc(p.id)}</small></div></div>`,esc(p.collection),money(Math.min(...Object.values(p.prices)))+'<small>From / A2</small>',U.statePill(p),link(ph(p),'Edit product','text-link')]}));return A.heading('Products','One catalogue. Images, prices and private originals kept together.',`<form class="filter-form" data-filter="products">${field('q','Search products',A.params.get('q')||'','search','',false)}${select('status','Visibility',[['All','All products'],['Active','Approved / demo published'],['Draft','Draft'],['In review','In review'],['Hidden','Paused'],['Retired','Archived']],status)}<button class="button secondary" type="submit">Apply</button>${link('products','Clear','text-link')}</form>`+U.dataTable('Product catalogue',['Product','Collection','Price','Visibility',''],rows,selected?.id)+pg.footer+(selected?editor(selected):`<div class="workspace-placeholder"><h2>Select a product to edit</h2><p>Its details, images and private print files will open here.</p></div>`),actions(button('art-new','New product'),link('products/general','General images','button secondary'),`<details class="record-menu"><summary>Catalogue tools</summary><div>${link('products/materials','Materials & suppliers')}${link('products/collections','Collection order')}${link('products/import','Import with preview')}${button('export','Export catalogue',{kind:'products'},'text-button')}</div></details>`));};
 A.forms['cms-details']=(d,{id,version})=>{S.guard('catalogue');const p=find(id);versionCheck(p,version);const prices=Object.fromEntries(['black','white','antique-gold'].map(k=>[k,Math.round(Number(d[k])*100)]));if(Object.values(prices).some(v=>!Number.isSafeInteger(v)||v<0))throw Error('Enter zero or a positive INR price. A positive price is required before publication.');if(!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(d.slug))throw Error('Use lowercase letters, numbers and hyphens in the URL slug.');if(S.state.products.some(x=>x.id!==id&&x.slug===d.slug))throw Error('That URL slug is already used.');const split=x=>String(x||'').split(',').map(x=>x.trim()).filter(Boolean);change(p,'Save catalogue draft',()=>{Object.assign(p,{title:d.title.trim(),slug:d.slug,copy:d.copy.trim(),collection:d.collection.trim(),style:d.style.trim(),rooms:split(d.rooms),moods:split(d.moods),prices,lead:d.lead,featured:!!d.featured,status:'Draft'});Object.assign(p.cms,{orientation:d.orientation,suggestedFrame:d.frame,palettes:split(d.palettes),hook:d.hook});},d.reason);A.clearDirty();A.render();A.toast('Draft saved locally. Historical purchases are unchanged.');};
 A.forms['cms-seo']=(d,{id,version})=>{S.guard('catalogue');const p=find(id);versionCheck(p,version);change(p,'Save SEO draft',()=>{Object.assign(p.cms,{seoTitle:d.seoTitle.trim(),seoDescription:d.seoDescription.trim(),alt:d.alt.trim(),searchKeywords:d.keywords||''});p.status='Draft';});A.clearDirty();A.render();A.toast('SEO draft saved locally.');};
 A.handlers['art-new']=()=>{S.guard('catalogue');modal('New product','Start with the approved A2 format and three frame finishes. Nothing is published.',field('title','Product name')+field('slug','URL slug','','text','For example: evening-in-gold')+field('collection','Collection',S.state.products[0]?.collection||'New collection'),d=>{if(!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(d.slug))throw Error('Use a lowercase slug with hyphens.');if(S.state.products.some(p=>p.slug===d.slug))throw Error('This URL slug is already used.');let id='DRAFT-'+Date.now().toString(36).toUpperCase();S.mutate(id,'Create catalogue draft',()=>S.state.products.push({id,slug:d.slug,title:d.title,copy:'',collection:d.collection,style:'',moods:[],rooms:[],prices:{black:0,white:0,'antique-gold':0},lead:'5-7 working days',featured:false,status:'Draft',version:1,history:[],sample:false,rights:false,fileApproved:false,fileVersion:'v1',image:'',newDraft:true,cms:{orientation:'Portrait',palettes:[],hook:'',seoTitle:d.title,seoDescription:'',alt:d.title,searchKeywords:'',media:{},suggestedFrame:'black'}}));history.replaceState(null,'','#products?id='+id);},'Create draft');};
 A.handlers['public-upload']=({id,slot,general=false})=>{S.guard('catalogue');const p=general?null:find(id),def=general?window.AdminSharedImages.find(x=>x.id===slot):slots.find(x=>x[0]===slot);if(!def)throw Error('Unknown public image slot.');const slotId=general?slot:id+'--'+slot+'--'+Date.now().toString(36),label=general?def.title:def[1],old=V.publicItems.find(x=>x.id===(general?slot:p.cms.media[slot])),version=p?.version;modal('Upload '+label,'This is a PUBLIC image slot. Keep confidential print masters in Private files. Your original image is retained locally.',inputFile('Public image')+textarea('alt','Image description',old?.alt||p?.cms.alt||label)+check('public','This image is intended for public display'),async d=>{if(!d.public)throw Error('Confirm that this image is intended for public display.');if(p)versionCheck(p,version);await V.addPublic(d.file,{id:slotId,product:p?.id||'',slot,alt:d.alt,general});if(p)change(p,'Upload public '+label,()=>{p.cms.media[slot]=slotId;p.status='Draft';p.imageNote='';});else S.mutate(slotId,'Upload shared public image',()=>{});},'Save image locally');};
 A.handlers['public-download']=async({id})=>{S.guard('catalogue');await V.downloadPublic(id);};
 A.handlers['public-remove']=({id,slot,general=false})=>{S.guard('catalogue');const p=general?null:find(id),slotId=general?slot:p.cms.media[slot];modal('Remove this local image override?','The approved public website is unchanged. Product-image bytes are retained for revision rollback; general overrides are removed from this browser.',check('confirm','Remove this current image override'),async d=>{if(!d.confirm)throw Error('Confirm removal.');if(general)await V.removePublic(slotId);if(p)change(p,'Remove public image override',()=>{delete p.cms.media[slot];p.status='Draft';});},'Remove override',true);};
 A.handlers['vault-unlock']=({after}={})=>{S.guard('catalogue');modal(V.hasVault?'Unlock private files':'Create a private-file passphrase','Keep the passphrase somewhere safe. There is no password reset for encrypted file contents. This vault is local to this browser, not a production admin login.',field('password','Vault passphrase','','password')+(!V.hasVault?field('confirm','Repeat passphrase','','password')+check('keep','I will keep my original files and an external backup'):''),async d=>{if(!V.hasVault&&!d.keep)throw Error('Confirm that you will keep an external copy of your original files.');await V.unlock(d.password,d.confirm);if(after)await V.downloadPrivate(after);},V.hasVault?'Unlock':'Create vault');};
 A.handlers['vault-lock']=()=>{V.lock();A.render();A.toast('Private vault locked.');};
 A.handlers['private-download']=async({id})=>{S.guard('catalogue');if(!V.isUnlocked)return A.handlers['vault-unlock']({after:id});await V.downloadPrivate(id);A.toast('Verified original downloaded. It was not compressed or published.');};
 A.handlers['private-upload']=({id,kind})=>{S.guard('catalogue');const p=find(id);if(!V.isUnlocked){A.handlers['vault-unlock']();return;}const nums=V.privateItems.filter(x=>x.product===id&&x.kind==='print').map(x=>Number(x.version.slice(1))),v=kind==='approval'?p.fileVersion:nums.length?'v'+(Math.max(...nums)+1):p.fileVersion;const version=p.version;modal(kind==='print'?'Upload a private print original':'Upload private approval evidence','Stored encrypted in this browser only. Maximum 100 MB per file. Existing versions are retained, including those pinned to released orders.',inputFile('Private file','.pdf,.tif,.tiff,.psd,.psb,.ai,.eps,.zip,.png,.jpg,.jpeg,.webp')+field('version','File version',v,'text','Use v1, v2, v3 and so on.')+textarea('note','Reference / notes','',false)+check('backup','I have kept the source file outside this browser'),async d=>{if(!d.backup)throw Error('Keep an external copy before uploading.');versionCheck(p,version);const stored=await V.addPrivate(d.file,{product:id,version:d.version,kind,note:d.note});change(p,kind==='print'?'Add private print version':'Add private approval evidence',()=>{if(kind==='print'){p.printFileId=stored.id;p.fileVersion=stored.version;p.fileApproved=false;p.sample=false;p.status='Draft';}else {p.approvalFileIds=p.approvalFileIds||[];p.approvalFileIds.push(stored.id);}});},'Save private original');};
 A.handlers['cms-approvals']=({id})=>{S.guard('settings');const p=find(id);modal('Review production approvals','These are your recorded checks in this prototype, not an automatic rights or print-quality assessment. New print versions require fresh file and sample approval.',check('rights','Rights / permission for this artwork checked',p.rights)+check('file','Current print version reviewed',p.fileApproved)+check('sample','Physical sample inspected and approved',p.sample)+textarea('reason','Approval reference / evidence'),d=>{if(p.printFileId&&!V.privateItems.some(x=>x.id===p.printFileId))throw Error('The current print original is missing. Restore it first.');change(p,'Record production approvals',()=>{p.rights=!!d.rights;p.fileApproved=!!d.file;p.sample=!!d.sample;p.approvalNote=d.reason;p.approvedBy=S.names[S.state.role];p.approvedAt=S.now();},d.reason);},'Record approvals');};
 A.handlers['art-publish']=({id})=>{S.guard('settings');const p=find(id),missing=checks(p);modal('Publish this product in the demo?','The public website stays exactly as approved. This updates local catalogue visibility only.',missing.length?notice('Fix these items first',missing.map(esc).join('<br>'),'warn'):facts([['Product',esc(p.title)],['Format','A2 / three finishes'],['Image processing','Uploaded public previews processed locally; approved references retained'],['Public deployment','Not connected - no public files will change']]),()=>{const problems=checks(p);if(problems.length)throw Error(problems.join(' '));change(p,'Publish catalogue demo',()=>{p.status='Active';p.publishedAt=S.now();p.everPublished=true;p.approvedBy=S.names.owner;});},'Publish in demo');};
 A.handlers['cms-delete']=({id})=>{S.guard('catalogue');const p=find(id);const used=()=>p.status!=='Draft'||p.everPublished||window.AdminCatalogue.some(x=>x.id===p.id)||S.state.orders.some(o=>o.items.some(i=>i.artId===p.id)||o.purchase?.some(i=>i.artId===p.id))||V.privateItems.some(f=>f.product===p.id);if(used())throw Error('Only unused new drafts without private files can be deleted. Pause or archive this product instead.');modal('Delete this unused draft?','Only this new local draft and its public image overrides will be removed. Existing public products and orders are unchanged.',check('confirm','Delete '+p.title),async d=>{if(!d.confirm)throw Error('Confirm deletion.');if(used())throw Error('This product now has references and cannot be deleted.');for(const file of V.publicItems.filter(x=>x.product===p.id))await V.removePublic(file.id);S.mutate(p.id,'Delete unused draft',()=>S.state.products.splice(S.state.products.indexOf(p),1));history.replaceState(null,'','#products');},'Delete draft',true);};
 A.screens['products/preview']=()=>{const p=find(A.params.get('id'));return A.heading('Product preview','A local content preview, not a changed public page.',`<div class="preview-product"><div class="preview-art">${image(p,'frame-'+p.cms.suggestedFrame)}</div><div><p class="eyebrow">${esc(p.collection)}</p><h2>${esc(p.title)}</h2><p>${esc(p.cms.hook)}</p><p>${esc(p.copy)}</p>${facts([['Art style',esc(p.style)],['Format','A2 / 42 x 59.4 cm'],['Finishes',Object.entries(p.prices).map(([k,v])=>esc(k)+' / '+money(v)).join('<br>')],['Lead time',esc(p.lead)],['Local visibility',U.statePill(p)]])}</div></div>`+details('SEO preview',`<h3>${esc(p.cms.seoTitle)}</h3><p>${esc(p.cms.seoDescription)}</p>`),actions(link(ph(p),'Back to editor','button secondary'),button('art-publish','Publish in demo',{id:p.id})));};
 A.screens['products/general']=()=>{const q=(A.params.get('q')||'').toLowerCase(),defs=window.AdminSharedImages.filter(x=>(x.title+' '+x.group).toLowerCase().includes(q));return A.heading('General images','Upload once for the shared references used by the approved product pages.',`<p class="inline-message">This library is public imagery only. Uploads preview locally. To apply your final images without editing code, download the replacement assets, merge their assets folder into your repo and redeploy.</p><form class="filter-form" data-filter="products/general">${field('q','Find a shared image',A.params.get('q')||'','search','',false)}<button class="button secondary">Search</button></form><div class="media-grid">${defs.map(x=>{const f=V.publicItems.find(f=>f.id===x.id&&f.general);return `<section class="media-card"><div class="media-preview"><img src="${esc(V.url(x.id)||'../'+x.src)}" alt="${esc(f?.alt||x.title)}" loading="lazy" data-fallback="${esc('../'+x.src)}"></div><div class="media-info"><p class="eyebrow">${esc(x.group)}</p><h3>${esc(x.title)}</h3><p class="small">${f?esc(f.name)+' / Local override':'Approved shared asset reference'}</p>${actions(button('public-upload',f?'Replace image':'Upload image',{slot:x.id,general:true},'button secondary small-button'),f?button('public-remove','Remove',{slot:x.id,general:true},'text-button'):'')}${details('Existing destinations',`<ul class="path-list">${x.targets.map(t=>`<li><code>${esc(decodeURIComponent(t))}</code></li>`).join('')}</ul>`)}</div></section>`;}).join('')}</div>`,actions(link('products','Back to products','button secondary'),button('shared-export','Download replacement assets')));};
 A.handlers['shared-export']=()=>{S.guard('catalogue');modal('Download general-image replacements','Only shared PUBLIC image overrides are included. Private print files and product drafts are excluded.',check('understand','I will back up the repo, merge the exported assets and redeploy when ready'),async d=>{if(!d.understand)throw Error('Confirm the replacement steps.');V.download(await V.exportShared(),'aalishaan-general-images.zip');},'Download assets');};
 window.StudioCMS={checks,slots,source,vaultBar,hydrate(){if(!S.state.signedIn)V.lock();},snapshot};
})();
